package chronicle;

import com.google.gson.Gson;
import com.google.gson.JsonObject;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import org.junit.Test;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * The drop ledger's bags count as obtained for dryness: a unique already looted
 * is never a chase, whether or not the stored collection log has caught up with
 * it (the unlock notification off, or the page not reopened since).
 */
public class LedgerObtainedTest
{
	private static JsonObject clog(String boss, long kc)
	{
		JsonObject clog = new JsonObject();
		JsonObject kcs = new JsonObject();
		kcs.addProperty(boss, kc);
		clog.add("kcs", kcs);
		return clog;
	}

	private static LocalStore.SourceRow row(String source, int kc, String... looted)
	{
		Set<String> names = new HashSet<>();
		Collections.addAll(names, looted);
		return new LocalStore.SourceRow(source, kc, kc, 0L, null, 0L, 0L, names, 0, 0);
	}

	private static Set<String> chased(JsonObject clog, List<LocalStore.SourceRow> sources)
	{
		Set<String> out = new HashSet<>();
		for (GrindBook.GrindRow g : new GrindBook(new Gson()).grinds(clog, sources))
		{
			out.add(g.boss + " / " + g.item);
		}
		return out;
	}

	// 156 Vorkath with a Draconic visage in the bag and nothing in the log: the
	// visage is owned, its twin is still the chase.
	@Test
	public void aLootedUniqueIsNotChased()
	{
		List<LocalStore.SourceRow> sources = new ArrayList<>();
		sources.add(row("Vorkath", 156, "draconic visage"));
		Set<String> chased = chased(clog("Vorkath", 156), sources);
		assertFalse(chased.toString(), chased.contains("Vorkath / Draconic visage"));
		assertTrue(chased.toString(), chased.contains("Vorkath / Skeletal visage"));
	}

	// The same rows read with the log alone still chase the visage: the fold is
	// what removes it, not the rate book.
	@Test
	public void theLogAloneStillChasesIt()
	{
		List<LocalStore.SourceRow> sources = new ArrayList<>();
		sources.add(new LocalStore.SourceRow("Vorkath", 156, 156, 0L, null, 0L, 0L, java.util.Collections.emptySet(), 0, 0));
		assertTrue(chased(clog("Vorkath", 156), sources).contains("Vorkath / Draconic visage"));
	}

	// The ledger is read by name across every source, as the site's was: a dragon
	// med helm looted off a Mad Angel is the same helm the Barrows page lists.
	@Test
	public void aNameLootedAnywhereCountsOnEveryPage()
	{
		List<LocalStore.SourceRow> sources = new ArrayList<>();
		sources.add(row("Mad Angel", 3, "dragon med helm"));
		Set<String> chased = chased(clog("Barrows Chests", 25), sources);
		assertFalse(chased.toString(), chased.contains("Barrows Chests / Dragon med helm"));
	}

	// A pet sitting in a bag is owned on the pet page's chase too.
	@Test
	public void aLootedPetIsNotAPetChase()
	{
		List<LocalStore.SourceRow> sources = new ArrayList<>();
		sources.add(row("Zalcano", 2023, "smolcano"));
		Map<String, GrindBook.PetChase> chases = new GrindBook(new Gson()).petChases(
			clog("Zalcano", 2023), sources, new java.util.HashMap<>(), new java.util.HashMap<>(),
			new JsonObject(), Collections.singletonList("Smolcano"));
		assertFalse(chases.keySet().toString(), chases.containsKey("smolcano"));
	}
}

package chronicle;

import java.lang.reflect.Field;
import java.lang.reflect.Method;
import javax.swing.SwingUtilities;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

/**
 * What a rebuild costs, and how often one is paid for.
 *
 * <p>The panel is asked to redraw far more often than the record changes: a
 * region load, a world hop and a push can all ask inside one tick, and the
 * sidebar keeps asking while the reader is looking at another plugin entirely.
 * These are the two guards that stop the same board being drawn for nobody.
 */
public class PanelRebuildCostTest
{
	private static Field field(String name) throws Exception
	{
		Field f = ChroniclePanel.class.getDeclaredField(name);
		f.setAccessible(true);
		return f;
	}

	private static void edt() throws Exception
	{
		SwingUtilities.invokeAndWait(() ->
		{
		});
	}

	private static ChroniclePanel panel() throws Exception
	{
		java.io.File dir = new java.io.File(System.getProperty("java.io.tmpdir"),
			"chronicle-rebuild-cost");
		dir.mkdirs();
		PanelPreviewTest.StubPlugin s = PanelPreviewTest.journalStub(dir.getPath(), "nobody");
		final ChroniclePanel[] hold = new ChroniclePanel[1];
		SwingUtilities.invokeAndWait(() -> hold[0] = new ChroniclePanel(s));
		return hold[0];
	}

	/**
	 * Three asks inside one tick are one board. The queued rebuild has not run
	 * yet, so it reads everything the later asks would have read.
	 */
	@Test
	public void asksInsideOneTickCoalesce() throws Exception
	{
		ChroniclePanel p = panel();
		Field builds = field("buildsRun");
		edt();
		long before = builds.getLong(p);

		p.update();
		p.update();
		p.update();
		edt();

		assertEquals("three asks in a tick drew three boards",
			1, builds.getLong(p) - before);
	}

	/** A rebuild that ran and then was asked for again is a second board. */
	@Test
	public void aLaterAskStillEarnsItsOwnBoard() throws Exception
	{
		ChroniclePanel p = panel();
		Field builds = field("buildsRun");
		edt();
		long before = builds.getLong(p);

		p.update();
		edt();
		p.update();
		edt();

		assertEquals(2, builds.getLong(p) - before);
	}

	/**
	 * Nothing is drawn for a panel the reader cannot see, and the moment they
	 * come back it is drawn once, however many pushes landed meanwhile.
	 */
	@Test
	public void aHiddenPanelIsNotDrawnAndIsOwedOneOnReturn() throws Exception
	{
		ChroniclePanel p = panel();
		Field builds = field("buildsRun");
		// The client has shown the panel at least once; until it has, isShowing
		// says nothing and every ask is honoured.
		field("everShown").setBoolean(p, true);
		edt();
		long before = builds.getLong(p);

		for (int i = 0; i < 20; i++)
		{
			p.update();
			edt();
		}
		assertEquals("a board was drawn for a panel nobody was looking at",
			0, builds.getLong(p) - before);
		assertTrue("the panel does not know it owes the reader a board",
			field("staleWhileHidden").getBoolean(p));

		// Coming back: the hierarchy listener cannot fire headless, so the return is
		// played by hand. Not exactly as it plays: the real listener sets everShown
		// TRUE, and this sets it false, which is what makes the guard below
		// short-circuit before it ever asks isShowing(). So this covers the
		// staleWhileHidden bookkeeping and NOT the visibility test beside it.
		field("staleWhileHidden").setBoolean(p, false);
		field("everShown").setBoolean(p, false);
		p.update();
		edt();
		assertEquals("the reader came back to the board they left",
			1, builds.getLong(p) - before);
	}

	/**
	 * TRAP: the guard above is only worth what the paths through it honour, and
	 * the sitting's own three second ticker used to go straight to rebuild().
	 *
	 * <p>So a reader on another plugin entirely had this board laid out and
	 * painted for them twenty times a minute, forever, and the guard that was
	 * written to stop exactly that never saw the calls. Fired by hand here, since
	 * waiting three seconds for it in a test is three seconds.
	 */
	@Test
	public void theSittingsOwnTickerIsNotDrawnForAHiddenPanel() throws Exception
	{
		ChroniclePanel p = panel();
		Field builds = field("buildsRun");
		field("everShown").setBoolean(p, true);
		Field t = field("homeTicker");
		javax.swing.Timer ticker = (javax.swing.Timer) t.get(p);
		edt();
		long before = builds.getLong(p);

		for (int i = 0; i < 5; i++)
		{
			final int n = i;
			SwingUtilities.invokeAndWait(() ->
			{
				for (java.awt.event.ActionListener l : ticker.getActionListeners())
				{
					l.actionPerformed(new java.awt.event.ActionEvent(ticker, n, "tick"));
				}
			});
			edt();
		}
		assertEquals("the sitting redrew itself for a panel nobody was looking at",
			0, builds.getLong(p) - before);
		assertTrue("and did not even know it owed the reader a board",
			field("staleWhileHidden").getBoolean(p));
	}

	/** The per-build memo is dropped at the top of each build, not kept. */
	@Test
	public void theMemoDoesNotOutliveTheBuild() throws Exception
	{
		ChroniclePanel p = panel();
		Method rebuild = ChroniclePanel.class.getDeclaredMethod("rebuild");
		rebuild.setAccessible(true);
		SwingUtilities.invokeAndWait(() ->
		{
			try
			{
				rebuild.invoke(p);
			}
			catch (Exception e)
			{
				throw new RuntimeException(e);
			}
		});
		assertEquals("the sources memo outlived its build",
			null, field("buildSources").get(p));
		assertEquals("the collection log memo outlived its build",
			null, field("buildClog").get(p));
	}
}

