package chronicle;

import com.google.gson.Gson;
import java.io.File;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.util.List;
import net.runelite.client.game.ItemManager;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.assertEquals;

/**
 * The uncollected ledger keeps the same leavings by source, by item and by the pair.
 * The pairs carry the detail, so the by-item totals are rebuilt from them on load,
 * but only when the pairs account for every source, since that is what makes them
 * safe to sum.
 */
public class UntakenReconcileTest
{
	private LocalStore store;
	private File dir;

	@Before
	public void setUp() throws Exception
	{
		store = new LocalStore(Mockito.mock(ItemManager.class), new Gson());
		dir = Files.createTempDirectory("chronicle-untaken").toFile();
	}

	private void write(String journal) throws Exception
	{
		Files.write(new File(dir, "tester.json").toPath(),
			journal.getBytes(StandardCharsets.UTF_8));
	}

	private long qtyOf(List<LocalStore.UntakenRow> rows, String item)
	{
		for (LocalStore.UntakenRow r : rows)
		{
			if (r.name.equals(item))
			{
				return r.qty;
			}
		}
		return -1;
	}

	@Test
	public void byItemTotalsAreRebuiltFromThePairs() throws Exception
	{
		// Bones is inflated and Swamp tar has no pair at all: the shape left behind
		// when something edits one store and not the others.
		write("{\"schema\":1,\"rsn\":\"Tester\","
			+ "\"untaken\":{\"Dust devil\":{\"qty\":12,\"value\":120}},"
			+ "\"untaken_items\":{\"Bones\":{\"qty\":999,\"value\":9990},"
			+ "\"Swamp tar\":{\"qty\":55,\"value\":550}},"
			+ "\"untaken_pairs\":{\"Dust devil\":{\"Bones\":{\"qty\":12,\"value\":120}}}}");
		store.load(dir, "Tester");
		List<LocalStore.UntakenRow> items = store.untakenItems();
		assertEquals(1, items.size());
		assertEquals(12, qtyOf(items, "Bones"));
		// the sourceless row is gone rather than standing on its own
		assertEquals(-1, qtyOf(items, "Swamp tar"));
	}

	@Test
	public void theByItemAndBySourceViewsAgreeAfterAReload() throws Exception
	{
		write("{\"schema\":1,\"rsn\":\"Tester\","
			+ "\"untaken\":{\"Dust devil\":{\"qty\":12,\"value\":120},"
			+ "\"Nechryael\":{\"qty\":5,\"value\":50}},"
			+ "\"untaken_items\":{\"Bones\":{\"qty\":999,\"value\":9990}},"
			+ "\"untaken_pairs\":{\"Dust devil\":{\"Bones\":{\"qty\":12,\"value\":120}},"
			+ "\"Nechryael\":{\"Bones\":{\"qty\":5,\"value\":50}}}}");
		store.load(dir, "Tester");
		long bySource = 0;
		for (LocalStore.UntakenRow r : store.untakenSources())
		{
			bySource += r.qty;
		}
		long byItem = 0;
		for (LocalStore.UntakenRow r : store.untakenItems())
		{
			byItem += r.qty;
		}
		assertEquals(17, bySource);
		assertEquals(bySource, byItem);
	}

	@Test
	public void aJournalWithNoPairsIsLeftAlone() throws Exception
	{
		// Written before the pair store existed: its by-item totals are all there is.
		write("{\"schema\":1,\"rsn\":\"Tester\","
			+ "\"untaken\":{\"Dust devil\":{\"qty\":12,\"value\":120}},"
			+ "\"untaken_items\":{\"Bones\":{\"qty\":999,\"value\":9990}}}");
		store.load(dir, "Tester");
		assertEquals(999, qtyOf(store.untakenItems(), "Bones"));
	}

	@Test
	public void pairsThatMissASourceAreNotTrustedToSumFrom() throws Exception
	{
		// Nechryael's leavings are known by source but have no pairs, so summing the
		// pairs would silently drop them.
		write("{\"schema\":1,\"rsn\":\"Tester\","
			+ "\"untaken\":{\"Dust devil\":{\"qty\":12,\"value\":120},"
			+ "\"Nechryael\":{\"qty\":5,\"value\":50}},"
			+ "\"untaken_items\":{\"Bones\":{\"qty\":17,\"value\":170}},"
			+ "\"untaken_pairs\":{\"Dust devil\":{\"Bones\":{\"qty\":12,\"value\":120}}}}");
		store.load(dir, "Tester");
		assertEquals(17, qtyOf(store.untakenItems(), "Bones"));
	}
}

package chronicle;

import java.awt.Component;
import java.awt.Container;
import java.io.File;
import java.io.FileWriter;
import java.lang.reflect.Method;
import java.util.ArrayList;
import java.util.List;
import javax.swing.JLabel;
import javax.swing.SwingUtilities;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * The counts-of-the-record page: what the journal holds, rather than what the
 * account has done.
 *
 * <p>It carries no date and no name anywhere, which is the point. It is the
 * page somebody hands over when they are being helped, so handing it over must
 * not hand over the account with it.
 */
public class InfoPageTest
{
	private static final String JOURNAL =
		"{\"schema\":1,\"rsn\":\"Somebody\",\"first_seen\":1600000000000,"
		+ "\"drops\":{"
		+ "\"Jelly\":{\"kc\":141,\"loots\":252,\"value\":1000,\"first_seen\":1600000000000,"
		+ "\"items\":{\"1\":{\"id\":1,\"name\":\"Chaos rune\",\"qty\":10,\"value\":600},"
		+ "\"2\":{\"id\":2,\"name\":\"Coins\",\"qty\":400,\"value\":400}}},"
		+ "\"Zulrah\":{\"kc\":7,\"loots\":9,\"value\":900,"
		+ "\"items\":{\"3\":{\"id\":3,\"name\":\"Zulrah's scales\",\"qty\":90,\"value\":900}}}"
		+ "},"
		+ "\"collection_log\":{\"finished\":214,\"available\":1717,"
		+ "\"slayer_kcs\":{\"Jellies\":979},\"kcs\":{\"Zulrah\":7}},"
		+ "\"slayer\":{\"completed\":2,\"tasks\":["
		+ "{\"task\":\"Jellies\",\"ts\":1700000000,\"kills\":10,\"monsters\":{\"Jelly\":10},"
		+ "\"items\":{\"Chaos rune\":{\"id\":1,\"qty\":5,\"value\":300}}}"
		+ "]},"
		+ "\"trackers\":{\"a\":1,\"b\":2,\"c\":3},\"skills\":{\"attack\":100},"
		+ "\"feed\":[{\"k\":1},{\"k\":2}],\"loot_days\":{\"2026-09-15\":{}}}";

	private static ChroniclePanel panel() throws Exception
	{
		File dir = new File(System.getProperty("java.io.tmpdir"), "chronicle-info-page");
		dir.mkdirs();
		try (FileWriter w = new FileWriter(new File(dir, "somebody.json")))
		{
			w.write(JOURNAL);
		}
		PanelPreviewTest.StubPlugin s = PanelPreviewTest.journalStub(dir.getPath(), "Somebody");
		final ChroniclePanel[] hold = new ChroniclePanel[1];
		SwingUtilities.invokeAndWait(() -> hold[0] = new ChroniclePanel(s));
		return hold[0];
	}

	private static List<String> say(ChroniclePanel p, String method, Object... args)
		throws Exception
	{
		final List<String> out = new ArrayList<>();
		SwingUtilities.invokeAndWait(() ->
		{
			try
			{
				Method m = args.length == 0
					? ChroniclePanel.class.getDeclaredMethod(method)
					: ChroniclePanel.class.getDeclaredMethod(method, String.class);
				m.setAccessible(true);
				List<Component> flat = new ArrayList<>();
				flatten((Component) (args.length == 0 ? m.invoke(p) : m.invoke(p, args)), flat);
				for (Component c : flat)
				{
					if (c instanceof JLabel && ((JLabel) c).getText() != null)
					{
						out.add(((JLabel) c).getText());
					}
				}
			}
			catch (Exception e)
			{
				throw new RuntimeException(e);
			}
		});
		return out;
	}

	private static void flatten(Component c, List<Component> out)
	{
		out.add(c);
		if (c instanceof Container)
		{
			for (Component k : ((Container) c).getComponents())
			{
				flatten(k, out);
			}
		}
	}

	private static String after(List<String> said, String label)
	{
		for (int i = 0; i < said.size() - 1; i++)
		{
			if (label.equals(said.get(i)))
			{
				return said.get(i + 1);
			}
		}
		return null;
	}

	private static boolean has(List<String> said, String what)
	{
		for (String s : said)
		{
			if (s.toLowerCase(java.util.Locale.ROOT)
				.contains(what.toLowerCase(java.util.Locale.ROOT)))
			{
				return true;
			}
		}
		return false;
	}

	/** Found by typing, from the first letter, because it has no tab. */
	@Test
	public void itIsFoundWhileBeingTyped() throws Exception
	{
		ChroniclePanel p = panel();
		for (String q : new String[]{"i", "in", "inf", "info"})
		{
			assertTrue("typing \"" + q + "\" did not offer it",
				has(say(p, "buildSearch", q), "what the journal holds"));
		}
		assertFalse("it was offered for something it does not spell",
			has(say(p, "buildSearch", "zzz"), "what the journal holds"));
	}

	/** Every figure is a count of the record, and they are the record's. */
	@Test
	public void itCountsWhatTheJournalHolds() throws Exception
	{
		ChroniclePanel p = panel();
		List<String> said = say(p, "buildInfo");
		assertEquals("2", after(said, "Sources"));
		assertEquals("3 item rows across two sources", "3", after(said, "Item rows"));
		assertEquals("252 + 9", "261", after(said, "Loot events"));
		assertEquals("1", after(said, "Dated days"));
		assertEquals("1", after(said, "Assignments"));
		assertEquals("2", after(said, "Closed"));
		assertEquals("214 of 1,717", after(said, "Slots filled"));
		assertEquals("1", after(said, "Kill Log lines"));
		assertEquals("3", after(said, "Trackers"));
		// not asserted: the store normalises the feed on load, so a fixture's
		// raw entry count is not what the page will report
		assertEquals("1", after(said, "Schema"));
	}

	/**
	 * Nothing on it names the account or dates it. The journal holds an rsn and
	 * a first_seen, and neither reaches this page.
	 */
	@Test
	public void itHandsOverNoAccount() throws Exception
	{
		ChroniclePanel p = panel();
		List<String> said = say(p, "buildInfo");
		assertFalse("the page names the account", has(said, "Somebody"));
		assertFalse(has(said, "Tracked since"));
		assertFalse(has(said, "2020"));
		assertFalse(has(said, "Sept"));
	}

	/**
	 * The back row leaves. It is not a page anybody drilled into, so it is not
	 * on the detail stack, and popping an empty stack left the reader standing
	 * on the page they were trying to leave.
	 */
	@Test
	public void theBackRowLeaves() throws Exception
	{
		ChroniclePanel p = panel();
		java.lang.reflect.Field f = ChroniclePanel.class.getDeclaredField("showInfo");
		f.setAccessible(true);
		f.setBoolean(p, true);
		java.lang.reflect.Method back =
			ChroniclePanel.class.getDeclaredMethod("backDetail");
		back.setAccessible(true);
		SwingUtilities.invokeAndWait(() ->
		{
			try
			{
				back.invoke(p);
			}
			catch (Exception e)
			{
				throw new RuntimeException(e);
			}
		});
		assertFalse("back left the reader on the page they were leaving",
			f.getBoolean(p));
	}

	/**
	 * A tab click leaves it, like a tab click leaves every other page a reader
	 * was sent to.
	 *
	 * <p>rebuild() tests showInfo BEFORE it looks at which view is up, so a
	 * flag left standing means every tab, every sub-tab and every search
	 * redraws the info page and the panel stops navigating at all. The back row
	 * was only half of it.
	 */
	@Test
	public void aTabClickLeavesIt() throws Exception
	{
		ChroniclePanel p = panel();
		java.lang.reflect.Field f = ChroniclePanel.class.getDeclaredField("showInfo");
		f.setAccessible(true);
		Class<?> tabType = Class.forName("chronicle.ChroniclePanel$Tab");
		java.lang.reflect.Method applyTab =
			ChroniclePanel.class.getDeclaredMethod("applyTab", tabType);
		applyTab.setAccessible(true);
		for (Object tab : tabType.getEnumConstants())
		{
			f.setBoolean(p, true);
			SwingUtilities.invokeAndWait(() ->
			{
				try
				{
					applyTab.invoke(p, tab);
				}
				catch (Exception e)
				{
					throw new RuntimeException(e);
				}
			});
			assertFalse("clicking " + tab + " left the reader on the info page",
				f.getBoolean(p));
		}
	}

	/** And so does opening anything from search. */
	@Test
	public void openingSomethingElseLeavesIt() throws Exception
	{
		ChroniclePanel p = panel();
		java.lang.reflect.Field f = ChroniclePanel.class.getDeclaredField("showInfo");
		f.setAccessible(true);
		f.setBoolean(p, true);
		java.lang.reflect.Method open =
			ChroniclePanel.class.getDeclaredMethod("openAllTrackers");
		open.setAccessible(true);
		SwingUtilities.invokeAndWait(() ->
		{
			try
			{
				open.invoke(p);
			}
			catch (Exception e)
			{
				throw new RuntimeException(e);
			}
		});
		assertFalse("all-trackers opened behind the info page", f.getBoolean(p));
	}
}

