		leave(a, b);
		List<JsonObject> rows = untakenRows();
		assertEquals(1, rows.size());
		assertEquals(BEAR, rows.get(0).get("source").getAsString());
		assertEquals(2, items(rows.get(0)));
		assertEquals(2, kills(rows.get(0)));
	}

