		List<String> filed = new ArrayList<>();
		for (HistoryProgress.Group g : p.groups())
		{
			for (HistoryProgress.Row r : g.rows())
			{
				assertFalse(r.key() + " files twice", filed.contains(r.key()));
				filed.add(r.key());
