package chronicle;

import java.awt.Color;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import net.runelite.client.ui.FontManager;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * The pets page prints a chase in one line: where the kills went, and the share of
 * players holding the pet by that point. The row is narrow and Swing clips the end
 * of a label, so the line is fitted before it is mounted. What is tested here is
 * the bargain that fitting strikes: the names give up letters, the figures give up
 * nothing, and that whatever comes back really does measure inside the row.
 */
public class ChaseLineFitTest
{
	@Before
	public void laf() throws Exception
	{
		System.setProperty("java.awt.headless", "true");
		// the client's own look and feel: its scrollbar is what the row's width is
		// reckoned against
		javax.swing.SwingUtilities.invokeAndWait(() ->
		{
			try
			{
				javax.swing.UIManager.setLookAndFeel(
					new net.runelite.client.ui.laf.RuneLiteLAF());
			}
			catch (Exception e)
			{
				throw new RuntimeException(e);
			}
		});
	}

	// Whatever mark the panel actually cuts with, so this test guards that and not
	// a copy of it.
	private static String ellipsis() throws Exception
	{
		java.lang.reflect.Field f = ChroniclePanel.class.getDeclaredField("ELLIPSIS");
		f.setAccessible(true);
		return (String) f.get(null);
	}

	private static GrindBook.PetChase boss(double pct, Object... bossKc)
	{
		java.util.List<GrindBook.PetSource> src = new java.util.ArrayList<>();
		for (int i = 0; i < bossKc.length; i += 2)
		{
			src.add(new GrindBook.PetSource((String) bossKc[i], (Long) bossKc[i + 1], 3000));
		}
		long total = 0;
		for (GrindBook.PetSource s : src)
		{
			total += s.kc;
		}
		return new GrindBook.PetChase("A pet", total, pct, src);
	}

	private static GrindBook.PetChase skilling(double pct, String activity, long kc, String unit)
	{
		return new GrindBook.PetChase("A pet", kc, pct, Collections.emptyList(),
			activity, unit, 99);
	}

	// The share the row draws on the right, exactly as the panel words it.
	private static String share(GrindBook.PetChase chase) throws Exception
	{
		java.lang.reflect.Method m =
			ChroniclePanel.class.getDeclaredMethod("holdShare", GrindBook.PetChase.class);
		m.setAccessible(true);
		return (String) m.invoke(null, chase);
	}

	// The whole sentence the row hands its hover, exactly as the panel words it.
	private static String tip(GrindBook.PetChase chase) throws Exception
	{
		java.lang.reflect.Method m =
			ChroniclePanel.class.getDeclaredMethod("chaseTip", GrindBook.PetChase.class);
		m.setAccessible(true);
		return (String) m.invoke(null, chase);
	}

	// A skilling chase, built with the sources the fitted line gave up naming.
	private static GrindBook.PetChase spread(double pct, String activity, String unit,
		Object... nameKc)
	{
		java.util.List<GrindBook.PetSource> src = new java.util.ArrayList<>();
		long total = 0;
		for (int i = 0; i < nameKc.length; i += 2)
		{
			src.add(new GrindBook.PetSource((String) nameKc[i], (Long) nameKc[i + 1], 3000));
			total += (Long) nameKc[i + 1];
		}
		return new GrindBook.PetChase("A pet", total, pct, src, activity, unit, 0);
	}

	// The one thing every case must satisfy: it fits the room the row actually has.
	private static void assertFits(String line, String share)
	{
		FontMetrics fm = ChroniclePanel.rowMetrics();
		int room = ChroniclePanel.chaseRoom(share, fm);
		assertTrue("[" + line + "] is " + fm.stringWidth(line) + "px in a " + room + "px row",
			fm.stringWidth(line) <= room);
	}

	// No figure may be printed part-read: every run of digits in the line has to be
	// one of the figures the chase holds, whole.
	private static void assertFiguresWhole(String line, String... figures) throws Exception
	{
		List<String> allowed = Arrays.asList(figures);
		Matcher m = Pattern.compile("[0-9][0-9,]*").matcher(line);
		while (m.find())
		{
			assertTrue("[" + line + "] prints a part-read figure: " + m.group(),
				allowed.contains(m.group()));
		}
		assertFalse("[" + line + "] cut a figure short",
			line.matches(".*[0-9]" + Pattern.quote(ellipsis()) + ".*"));
	}

	@Test
	public void aShortNameIsLeftCompletelyAlone() throws Exception
	{
		GrindBook.PetChase c = boss(0.4, "Abyssal Sire", 214L);
		String line = ChroniclePanel.fitChase(c, share(c));
		assertEquals("Abyssal Sire, kc 214", line);
		assertFalse("nothing was too wide, so nothing should be cut",
			line.contains(ellipsis()));
		assertFits(line, share(c));
	}

	@Test
	public void oneLongNameGivesLettersAndKeepsItsCount() throws Exception
	{
		GrindBook.PetChase c = boss(37, "Thermonuclear Smoke Devil", 1402L);
		String line = ChroniclePanel.fitChase(c, share(c));
		assertTrue(line + " lost its count", line.endsWith(", kc 1,402"));
		// enough of the name to know the boss on sight
		assertTrue(line + " is not recognisable as the boss",
			line.startsWith("Thermonu"));
		assertTrue(line + " should say it was cut", line.contains(ellipsis()));
		assertFiguresWhole(line, "1,402");
		assertFits(line, share(c));
	}

	@Test
	public void twoLongSourcesKeepEveryCountTheyShow() throws Exception
	{
		GrindBook.PetChase c = boss(73, "Callisto", 1500L, "Artio", 900L);
		String line = ChroniclePanel.fitChase(c, share(c));
		// the source that carried the grind is named in full, whatever else goes
		assertTrue(line + " mangled the leading source",
			line.startsWith("Callisto, kc 1,500"));
		assertFiguresWhole(line, "1,500", "900", "1");
		if (!line.contains("Artio"))
		{
			// dropped rather than mangled, and the row says so
			assertFalse(line + " kept a stub of the second source",
				line.contains("Art" + ellipsis()));
			assertTrue(line + " dropped a source without saying so", line.endsWith(" +1"));
		}
		else
		{
			assertTrue(line + " lost the second count", line.contains(", kc 900"));
		}
		assertFits(line, share(c));
	}

	/**
	 * Two names that would both fit if both were cut. They are not both cut: the
	 * source that carried the grind is named in full and the other one gives way,
	 * because a line that reads "Cha…, kc 1 · Cra…, kc 1" names nothing at all.
	 */
	@Test
	public void theLeadingSourceIsNeverCutWhileATrailingOneCanGiveWay() throws Exception
	{
		GrindBook.PetChase c = boss(0.4, "Chaos Fanatic", 1L, "Crazy archaeologist", 1L);
		String line = ChroniclePanel.fitChase(c, share(c));
		assertTrue(line + " cut into the leading source",
			line.startsWith("Chaos Fanatic, kc 1"));
		assertFiguresWhole(line, "1");
		assertFits(line, share(c));
	}

	@Test
	public void aNameSoLongNothingFitsStillPrintsTheCount() throws Exception
	{
		StringBuilder monster = new StringBuilder();
		for (int i = 0; i < 200; i++)
		{
			monster.append('W');
		}
		GrindBook.PetChase c = boss(37, monster.toString(), 1402L);
		String line = ChroniclePanel.fitChase(c, share(c));
		assertTrue(line + " lost its count", line.endsWith(", kc 1,402"));
		assertTrue(line + " kept none of the name", line.startsWith("WWW"));
		assertTrue(line + " should say it was cut", line.contains(ellipsis()));
		assertFiguresWhole(line, "1,402");
		assertFits(line, share(c));
	}

	@Test
	public void theSkillingLineKeepsItsCountToo() throws Exception
	{
		GrindBook.PetChase c = skilling(3, "Runecraft", 30112L, "essence");
		String line = ChroniclePanel.fitChase(c, share(c));
		assertTrue(line + " lost its activity", line.startsWith("Runecraft"));
		assertTrue(line + " lost its count", line.contains(", 30,112 "));
		assertFiguresWhole(line, "30,112");
		assertFits(line, share(c));
	}

	@Test
	public void aSkillingLineThatAlreadyFitsIsNotTouched() throws Exception
	{
		GrindBook.PetChase c = skilling(6, "Mining", 9923L, "ore");
		String line = ChroniclePanel.fitChase(c, share(c));
		assertEquals("Mining, 9,923 ore", line);
		assertFits(line, share(c));
	}

	/**
	 * The font the panel draws rows in is a pixel font with holes in it. An em dash
	 * is why none of these strings carry one. The single-character ellipsis is not
	 * one of the holes: it paints three pixels, where a glyph the font lacks paints
	 * the .notdef box instead.
	 */
	@Test
	public void theEllipsisIsAGlyphTheGameFontHas() throws Exception
	{
		java.awt.Font f = FontManager.getRunescapeFont();
		String mark = ellipsis();
		for (char ch : mark.toCharArray())
		{
			assertTrue("the game font has no " + ch, f.canDisplay(ch));
			int drawn = ink(f, ch);
			int missing = ink(f, '█');   // a full block: the font has no such glyph
			assertTrue(ch + " painted nothing", drawn > 0);
			assertTrue(ch + " painted the .notdef box, not a glyph", drawn < missing / 4);
		}
	}

	// Pixels a glyph actually paints at the row's own size.
	private static int ink(java.awt.Font f, char ch)
	{
		BufferedImage im = new BufferedImage(40, 40, BufferedImage.TYPE_INT_RGB);
		Graphics2D g = im.createGraphics();
		g.setColor(Color.BLACK);
		g.fillRect(0, 0, 40, 40);
		g.setFont(f);
		g.setColor(Color.WHITE);
		g.drawString(String.valueOf(ch), 8, 28);
		g.dispose();
		int n = 0;
		for (int y = 0; y < 40; y++)
		{
			for (int x = 0; x < 40; x++)
			{
				if ((im.getRGB(x, y) & 0xFFFFFF) != 0)
				{
					n++;
				}
			}
		}
		return n;
	}

	// The hover names the source that carried a grind because the fitted line spent
	// itself on the activity instead. Where the activity IS the source there is
	// nothing to disclose, and the clause repeats the line back at itself: "Mad
	// Angel, 124 kills, mostly mad angel".
	@Test
	public void aSingleSourceChaseDoesNotNameItselfTwice() throws Exception
	{
		GrindBook.PetChase c = spread(6.0, "Mad Angel", "kills", "Mad Angel", 124L);
		String tip = tip(c);
		assertEquals("6% of players have A pet by this point. Mad Angel, 124 kills.", tip);
		assertFalse("[" + tip + "] said the source twice", tip.contains("mostly"));
	}

	// Two sources and the clause earns its place: the line said Woodcutting and the
	// count, and the hover says which tree most of it was.
	@Test
	public void aSpreadChaseStillNamesTheSourceThatCarriedIt() throws Exception
	{
		GrindBook.PetChase c = spread(41.0, "Woodcutting", "logs",
			"Yew trees", 14_204L, "Willow trees", 5_185L);
		String tip = tip(c);
		assertTrue("[" + tip + "] dropped the clause that earns its place",
			tip.endsWith("Woodcutting, 19,389 logs, mostly yew trees."));
	}

	// A boss chase names its sources outright in the line, so the clause was never
	// its business either way.
	@Test
	public void aBossChaseNeverTakesTheClause() throws Exception
	{
		GrindBook.PetChase c = boss(37.0, "Callisto", 1_500L, "Artio", 900L);
		String tip = tip(c);
		assertFalse("[" + tip + "] took a clause meant for a skilling grind",
			tip.contains("mostly"));
	}
}

package chronicle;

import java.awt.Component;
import java.awt.Container;
import java.io.File;
import java.io.FileWriter;
import java.lang.reflect.Field;
import java.lang.reflect.Method;
import java.util.ArrayList;
import java.util.List;
import javax.swing.JLabel;
import javax.swing.SwingUtilities;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * The ledger read by what a thing IS rather than by what dropped it.
 *
 * <p>Every assertion here is a number or a control a reader would believe: a
 * head that totals the wrong bag, a count of items called a count of kinds, a
 * lens that disappears when the period changes. None of them throw.
 */
public class LootByKindTest
{
	private static final String JOURNAL =
		"{\"drops\":{"
		+ "\"Abyssal demon\":{\"kc\":100,\"value\":300,\"items\":{"
		+ "\"1\":{\"id\":1,\"name\":\"Fire rune\",\"qty\":400,\"value\":200},"
		+ "\"2\":{\"id\":2,\"name\":\"Death rune\",\"qty\":50,\"value\":100},"
		+ "\"3\":{\"id\":3,\"name\":\"Rune scimitar\",\"qty\":2,\"value\":30000}"
		+ "}}}}";

	private static ChroniclePanel panel() throws Exception
	{
		File dir = new File(System.getProperty("java.io.tmpdir"), "chronicle-by-kind");
		dir.mkdirs();
		try (FileWriter w = new FileWriter(new File(dir, "kindly.json")))
		{
			w.write(JOURNAL);
		}
		PanelPreviewTest.StubPlugin s = PanelPreviewTest.journalStub(dir.getPath(), "kindly");
		final ChroniclePanel[] hold = new ChroniclePanel[1];
		SwingUtilities.invokeAndWait(() -> hold[0] = new ChroniclePanel(s));
		return hold[0];
	}

	private static void set(ChroniclePanel p, String name, Object v) throws Exception
	{
		Field f = ChroniclePanel.class.getDeclaredField(name);
		f.setAccessible(true);
		f.set(p, v);
	}

	/** The Drops board as it would be drawn, with the fields the test set. */
	private static List<String> board(ChroniclePanel p) throws Exception
	{
		final List<String> said = new ArrayList<>();
		SwingUtilities.invokeAndWait(() ->
		{
			try
			{
				Method m = ChroniclePanel.class.getDeclaredMethod("buildDrops");
				m.setAccessible(true);
				List<Component> flat = new ArrayList<>();
				flatten((Component) m.invoke(p), flat);
				for (Component c : flat)
				{
					if (c instanceof JLabel && ((JLabel) c).getText() != null)
					{
						said.add(((JLabel) c).getText());
					}
				}
			}
			catch (Exception e)
			{
				throw new RuntimeException(e);
			}
		});
		return said;
	}

	private static void flatten(Component c, List<Component> out)
	{
		out.add(c);
		if (c instanceof Container)
		{
			for (Component k : ((Container) c).getComponents())
			{
				flatten(k, out);
			}
		}
	}

	private static boolean says(List<String> said, String what)
	{
		for (String s : said)
		{
			if (s.contains(what))
			{
				return true;
			}
		}
		return false;
	}

	/**
	 * The lens is a control on the board, not a control on one period.
	 *
	 * <p>Including the sitting, which briefly had no axis because the dated roll
	 * keeps one entry a day and so could not be asked what a few hours took. The
	 * sitting keeps its own entry now, in the same shape, so it has two readings
	 * like every other period and is offered the control that swaps them.
	 */
	@Test
	public void theKindLensIsOfferedAtEveryPeriod() throws Exception
	{
		ChroniclePanel p = panel();
		for (String period : ChroniclePanel.PERIODS)
		{
			set(p, "histGranularity", period);
			List<String> said = board(p);
			// One toggle carrying the reading it is on, so only one of the two
			// labels is ever drawn. The rule is that the axis is OFFERED here.
			assertTrue("the grouping control vanished at " + period + ": " + said,
				says(said, "By kind") || says(said, "By source"));
		}
	}

	/** Left behind is a list of items already; there is nothing to regroup. */
	@Test
	public void theLensIsNotOfferedOnWhatWasLeft() throws Exception
	{
		ChroniclePanel p = panel();
		set(p, "histGranularity", "Lifetime");
		set(p, "dropsLeftBehind", true);
		assertFalse("a grouping control was offered over left-behind items",
			says(board(p), "By kind"));
	}

	/** A drilled kind totals THAT kind. The bag's own totals are a lie under it. */
	@Test
	public void aDrilledKindTotalsItself() throws Exception
	{
		ChroniclePanel p = panel();
		set(p, "histGranularity", "Lifetime");
		set(p, "dropsByKind", true);
		set(p, "lootKind", "Runes");
		List<String> said = board(p);
		assertTrue("the head is not the kind's", says(said, "Runes"));
		// 400 fire + 50 death = 450 items, worth 300. The bag is 452 items
		// worth 30,300, and that is what the head used to say.
		assertTrue("the head did not total the kind", says(said, "450"));
		assertFalse("the head totalled the whole bag under the kind's name",
			says(said, "452"));
		assertTrue("two runes are two distinct items", says(said, "2 items"));
	}

	/** A kind the bag holds none of says so rather than drawing nothing. */
	@Test
	public void anEmptyKindSaysSo() throws Exception
	{
		ChroniclePanel p = panel();
		set(p, "histGranularity", "Lifetime");
		set(p, "dropsByKind", true);
		set(p, "lootKind", "Herbs");
		List<String> said = board(p);
		assertTrue("an empty kind drew a blank board",
			says(said, "Nothing of this kind"));
		assertTrue("there was no way back out of it", says(said, "All kinds"));
	}

	/** The summary counts distinct items, and does not call them kinds. */
	@Test
	public void theSummaryCallsItemsItems() throws Exception
	{
		ChroniclePanel p = panel();
		set(p, "histGranularity", "Lifetime");
		set(p, "dropsByKind", true);
		List<String> said = board(p);
		assertTrue("the kinds are not listed", says(said, "Runes"));
		assertTrue("the kinds are not listed", says(said, "Weapons"));
		assertFalse("a count of items was called a count of kinds",
			says(said, "kinds of thing"));
	}

	/** Reading by kind is a lens, and survives a look at another tab. */
	@Test
	public void theLensSurvivesATabMove() throws Exception
	{
		ChroniclePanel p = panel();
		set(p, "dropsByKind", true);
		Field f = ChroniclePanel.class.getDeclaredField("dropsByKind");
		f.setAccessible(true);
		Method common = null;
		int overloads = 0;
		for (Method m : ChroniclePanel.class.getDeclaredMethods())
		{
			if (m.getName().equals("applyCommon"))
			{
				common = m;
				overloads++;
			}
		}
		assertEquals("applyCommon is gone or has a second overload", 1, overloads);
		final Method call = common;
		call.setAccessible(true);
		SwingUtilities.invokeAndWait(() ->
		{
			try
			{
				call.invoke(p, callArgs(call));
			}
			catch (Exception e)
			{
				throw new RuntimeException(e);
			}
		});
		assertTrue("a tab move put the reader back on sources", f.getBoolean(p));
	}

	/** Whatever applyCommon takes, called with nothing in particular. */
	private static Object[] callArgs(Method m) throws Exception
	{
		Object[] args = new Object[m.getParameterCount()];
		for (int i = 0; i < args.length; i++)
		{
			Class<?> t = m.getParameterTypes()[i];
			args[i] = t.isEnum() ? t.getEnumConstants()[0] : null;
		}
		return args;
	}
}

