		for (String label : new String[]{"Damage taken", "Hits missed", "Fishing",
			"Vials shattered", "Food", "The purse", "Uncollected loot", "Coins from alchemy",
			"Odds & ends", "Examines", "Teleports", "Destinations", "Varrock", "On foot",
