		s.bags.put("Zalcano", Arrays.asList(
			// the dearest carries no id, the way the imported rows do
			new LocalStore.BagItem(0, "Crystal tool seed", 2, 46_173_662L),
			new LocalStore.BagItem(23_962, "Crystal shard", 4_340, 0L)));

