	@Test
	public void slayerFinishedSplitsCountAndCreature()
	{
		Matcher m = ChronicleEventCapture.SLAYER_FINISHED.matcher("You have completed your task! You killed 1,000 hellhounds.");
		assertTrue(m.find());
