		assertEquals(1, j.tasks.get(0).kills);
		assertEquals(130, j.tasks.get(0).assignment);
		assertFalse(j.tasks.get(1).inProgress);
		assertEquals(150, j.tasks.get(1).kills);
		assertEquals(148, j.tasks.get(1).noLootKills);
	}

	@Test
